const now=()=>new Date(),parts=(d,tz)=>Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(d)).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));
