async function send(action,p){if(saving)throw Error('Please wait for the current save.');saving=true;const buttons=[...document.querySelectorAll('button,input,textarea,select')].filter(b=>!b.disabled);buttons.forEach(b=>b.disabled=true);try{const body=['cancel','refresh','link','delete'].includes(action)?{id:p.id,version:p.version}:Object.fromEntries(['id','version','title','copy','targets','copies','asset','assets','media_copies','format','ai_context','copy_history','type','tz','due','options'].map(k=>[k,p[k]??(k==='copies'?{}:null)]));body.copies=body.copies||{};body.assets=body.assets||postMediaKeys(p);body.media_copies=body.media_copies||{};body.format=body.format||(p.type==='Reel'?'video':(body.assets.length>1?'carousel':'image'));body.ai_context=body.ai_context||{};body.copy_history=body.copy_history||[];const r=await fetch(boot.base+'/'+action,{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':boot.csrf},body:JSON.stringify(body)});const data=await r.json().catch(()=>({message:'Your session may have expired. Sign in and reload the saved version; your current edits remain here.'}));if(!r.ok)throw Error(Object.values(data.errors||{}).flat().join(' ')||data.message||'Could not save. Your edits are retained.');const i=posts.findIndex(x=>x.id===data.post.id);if(i<0)posts.unshift(data.post);else posts[i]=data.post;return data.post;}finally{saving=false;buttons.forEach(b=>{if(b.isConnected)b.disabled=false;});}}
function notice(text){$('notice').textContent=text;$('notice').hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('notice').hidden=true,5000);}
