const route=()=>location.hash.slice(1)||boot.page;
function nav(){const links=[['overview','grid-fill','Overview'],['campaigns','flag','Campaigns'],['posts','file-earmark-text','Posts'],['calendar','calendar3','Calendar'],['analytics','bar-chart-line','Analytics'],['content','collection-play','Content Library'],['channels','share','Channels']];const selected=route().startsWith('calendar')?'calendar':'posts';$('navigation').innerHTML=links.map(([id,icon,name])=>`<li class="sidebar-menu-item"><a class="sidebar-menu-link ${selected===id?'active':''}" href="${['posts','calendar'].includes(id)?'#'+id:boot.urls[id]}">${ico(icon)}<span>${name}</span></a></li>`).join('');}
function go(to,force=false){if(dirty&&!force){modal('Keep your changes?',`<p class="muted">Your latest edits have not been saved.</p><div class="dialog-actions"><button class="btn-crm-secondary" data-close>Keep editing</button><button class="btn-crm-primary" data-action="discard" data-to="${esc(to)}">Discard changes</button></div>`);return;}if(force){dirty=false;working=null;}$('dialog').close();if(route()===to)render();else location.hash=to;}
