function campaignReturn(){const id=new URLSearchParams(location.search).get('campaign');const p=working||posts.find(p=>p.id===location.hash.split('/')[1]);if(!id||p?.campaign_id!==id||!/^[-a-f0-9]{36}$/i.test(id))return '';return ` · <a href="/admin/marketing/campaigns#campaign/${id}/content">Back to campaign</a>`;}
function heading(title,subtitle,breadcrumb='MARKETING STUDIO',actions=''){document.title=title+' · JW Marketing Studio';$('title').textContent=title;$('subtitle').textContent=subtitle;$('breadcrumb').innerHTML=breadcrumb+campaignReturn();$('page-action').innerHTML=actions;}
