document.addEventListener('change',async e=>{if(e.target.id!=='v2-upload'||!working)return;if(!boot.canEdit||uploading)return;capture();const sourceId=working.id,sourceTab=v2Tab,files=[...e.target.files],originalKeys=clone(postMediaKeys(working,v2MediaTarget()));if(files.length+originalKeys.length>10){notice('Choose up to 10 images.');return;}const added=[];uploading=true;$('dialog').close();renderEditor(sourceId);try{for(const file of files){if(file.size>10*1024*1024)throw Error('Choose images up to 10 MB each.');const asset=await new Promise((resolve,reject)=>{const body=new FormData();body.append('file',file);const x=new XMLHttpRequest();x.open('POST',boot.base.replace(/data$/,'upload'));x.setRequestHeader('Accept','application/json');x.setRequestHeader('X-CSRF-TOKEN',boot.csrf);x.upload.onprogress=e=>{if(e.lengthComputable)uploadPercent=Math.min(99,Math.round(e.loaded/e.total*100));if($('upload-feedback'))$('upload-feedback').innerHTML=uploadFeedback();};x.onload=()=>{let d;try{d=JSON.parse(x.responseText);}catch{reject(Error('Upload could not be confirmed. Your original is retained.'));return;}x.status>=200&&x.status<300?resolve(d.asset):reject(Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Upload failed.'));};x.onerror=()=>reject(Error('Upload stopped. Your original is retained.'));x.send(body);});assets.push(asset);added.push(asset.id);}}catch(e){notice(e.message);}finally{uploading=false;uploadPercent=0;if(working?.id===sourceId){v2Tab=sourceTab;v2SetMedia([...originalKeys.filter(k=>media(k)?.kind==='image'),...added]);working.type='Post';working.format=postMediaKeys(working,v2MediaTarget()).length>1?'carousel':'image';renderEditor(sourceId);}if(added.length)notice(added.length+' image(s) ready. Nothing has been published.');}});

